selector_to_html = {"a[href=\"#multi-platform-training-and-testing\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Training and Testing<a class=\"headerlink\" href=\"#multi-platform-training-and-testing\" title=\"Link to this heading\">#</a></h1><p>This guide walks through installing Megatron-LM-FL and running an end-to-end Qwen3 training job on four non-NVIDIA platforms: MetaX, Hygon, Ascend, and T-Head PPU. Every command, configuration file, and log excerpt below was collected from a real validation run on each platform.</p><p>The workflow uses three FlagOS components together:</p>", "a[href=\"#prepare-the-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Prepare the environment<a class=\"headerlink\" href=\"#prepare-the-environment\" title=\"Link to this heading\">#</a></h2><h3>2.1 Clone the repositories<a class=\"headerlink\" href=\"#clone-the-repositories\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#launch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.3 Launch<a class=\"headerlink\" href=\"#launch\" title=\"Link to this heading\">#</a></h3><p>Watch device utilization while training runs:</p>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#task-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.2 Task configuration<a class=\"headerlink\" href=\"#task-configuration\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train.yaml</span></code> so that the selected model config matches the file name, and set the platform device variable:</p>", "a[href=\"#run-the-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Run the training test<a class=\"headerlink\" href=\"#run-the-training-test\" title=\"Link to this heading\">#</a></h2><h3>5.1 Model configuration<a class=\"headerlink\" href=\"#model-configuration\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train/0_6b.yaml</span></code> to point at the local dataset and tokenizer, and shrink the batch sizes so the job fits a single node:</p>", "a[href=\"#model-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.1 Model configuration<a class=\"headerlink\" href=\"#model-configuration\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train/0_6b.yaml</span></code> to point at the local dataset and tokenizer, and shrink the batch sizes so the job fits a single node:</p>", "a[href=\"#clone-the-repositories\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Clone the repositories<a class=\"headerlink\" href=\"#clone-the-repositories\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#t-head-ppu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.4 T-Head PPU<a class=\"headerlink\" href=\"#t-head-ppu\" title=\"Link to this heading\">#</a></h3><p><strong>FlagTree and FlagGems cannot be compiled on <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code></strong> \u2014 see the note in section 6.1. Build from local disk.</p><p><strong>FlagCX is not enabled</strong> \u2014 the FlagCX path is known to fail on this platform; keep <code class=\"docutils literal notranslate\"><span class=\"pre\">distributed_backend</span></code> on the vendor collective library.</p>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.3 Ascend<a class=\"headerlink\" href=\"#ascend\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError:</span> <span class=\"pre\">'&lt;'</span> <span class=\"pre\">not</span> <span class=\"pre\">supported</span> <span class=\"pre\">between</span> <span class=\"pre\">instances</span> <span class=\"pre\">of</span> <span class=\"pre\">'NoneType'</span> <span class=\"pre\">and</span> <span class=\"pre\">'int'</span></code></strong> \u2014 on NPU devices <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.get_device_properties(...).major</span></code> returns <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code>, so the Blackwell check <code class=\"docutils literal notranslate\"><span class=\"pre\">get_device_arch_version()</span> <span class=\"pre\">&lt;</span> <span class=\"pre\">10</span></code> fails. The code path is only reached when <code class=\"docutils literal notranslate\"><span class=\"pre\">tensor_model_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">context_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code>, which is why single-card runs pass and multi-card runs fail. Patch <code class=\"docutils literal notranslate\"><span class=\"pre\">get_device_arch_version()</span></code> so non-NVIDIA devices return a value below 10:</p>", "a[href=\"#prepare-the-dataset-and-tokenizer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Prepare the dataset and tokenizer<a class=\"headerlink\" href=\"#prepare-the-dataset-and-tokenizer\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#switch-to-the-flagos-compiler-and-operator-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Switch to the FlagOS compiler and operator library<a class=\"headerlink\" href=\"#switch-to-the-flagos-compiler-and-operator-library\" title=\"Link to this heading\">#</a></h2><p>The training job above uses the vendor operator library. To run on the FlagOS stack instead, replace Triton with FlagTree and install FlagGems.</p>", "a[href=\"#install-flaggems\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.2 Install FlagGems<a class=\"headerlink\" href=\"#install-flaggems\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#expected-output\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.4 Expected output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h3><p>A healthy single-card run on Ascend (Qwen3, <code class=\"docutils literal notranslate\"><span class=\"pre\">global_batch_size:</span> <span class=\"pre\">32</span></code>):</p>", "a[href=\"#hygon\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.2 Hygon<a class=\"headerlink\" href=\"#hygon\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">gradient_accumulation_fusion</span></code> requires APEX CUDA extensions</strong> \u2014 disable it in the task configuration:</p>", "a[href=\"#supported-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Supported platforms<a class=\"headerlink\" href=\"#supported-platforms\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#start-the-container\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Start the container<a class=\"headerlink\" href=\"#start-the-container\" title=\"Link to this heading\">#</a></h3><p>MetaX:</p>", "a[href=\"#enter-the-container-and-verify-the-devices\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 Enter the container and verify the devices<a class=\"headerlink\" href=\"#enter-the-container-and-verify-the-devices\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-megatron-lm-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install Megatron-LM-FL<a class=\"headerlink\" href=\"#install-megatron-lm-fl\" title=\"Link to this heading\">#</a></h2><p>Verify the installed version:</p>", "a[href=\"#install-flagtree\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.1 Install FlagTree<a class=\"headerlink\" href=\"#install-flagtree\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#enable-the-flagos-stack-in-training\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.3 Enable the FlagOS stack in training<a class=\"headerlink\" href=\"#enable-the-flagos-stack-in-training\" title=\"Link to this heading\">#</a></h3><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train_te_fl.yaml</span></code> together with <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train/te_fl.yaml</span></code> and select the FlagOS backends:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
